'use strict';
function metricIcon(symbol){const paths={"▤": "<path d=\"M8 5H5v16h14V5h-3\"/><rect x=\"8\" y=\"3\" width=\"8\" height=\"4\" rx=\"1\"/><path d=\"M8 11h8M8 15h8\"/>", "⚑": "<path d=\"m12 3 10 18H2L12 3zM12 9v5M12 17v.1\"/>", "↗": "<path d=\"M5 19 19 5M5 5h14v14\"/>", "✓": "<path d=\"m4 12 5 5L20 6\"/>"};return '<svg viewBox="0 0 24 24" aria-hidden="true">'+(paths[symbol]||paths['▤'])+'</svg>';}
const STAGES=['Receiving','Inspection','Disposition','Resale inventory','Closed'];
const KEY='hpe-revolve-twin-v1';
const NOW=new Date('2026-11-12T15:00:00-06:00');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>new Date(s).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
const elapsed=r=>Math.max(0,Math.floor((Math.max(Date.now(),NOW.getTime())-new Date(r.created))/86400000));
function seed(){return [
 ['RV-1048','RMA-803492','HPE ProLiant DL380 Gen11','CZJ42801KL','Northstar Financial',0,'Maya Chen',2,'Missing RMA authorization','High'],
 ['RV-1047','RMA-803481','HPE Aruba CX 6300','SG42K901P2','Summit Health',1,'Jordan Lee',3,'Serial number mismatch','High'],
 ['RV-1046','RMA-803477','HPE Alletra 6010','CZJ31902AB','Atlas Manufacturing',2,'Alex Rivera',5,'Disposition approval pending','Medium'],
 ['RV-1045','RMA-803460','HPE ProLiant DL360 Gen10','CZJ21803CX','Meridian Systems',3,'Sam Patel',1,'',''],
 ['RV-1044','RMA-803452','HPE Aruba AP-635','CNK43721Q9','Oakwood University',1,'Jordan Lee',1,'',''],
 ['RV-1043','RMA-803441','HPE ProLiant DL380 Gen10','CZJ11900LM','Apex Logistics',0,'Maya Chen',0,'',''],
 ['RV-1042','RMA-803429','HPE MSA 2060','2S612901FX','Greenfield Energy',2,'Alex Rivera',4,'',''],
 ['RV-1041','RMA-803410','HPE Aruba CX 6200','SG40J221L3','Westbridge Retail',3,'Sam Patel',2,'',''],
 ['RV-1040','RMA-803399','HPE ProLiant DL360 Gen11','CZJ42901TG','Clearwater Labs',4,'Sam Patel',6,'',''],
 ['RV-1039','RMA-803388','HPE Aruba AP-515','CNM32891D8','Northstar Financial',4,'Sam Patel',7,'',''],
 ['RV-1038','RMA-803375','HPE ProLiant DL380 Gen10','CZJ21942BB','Summit Health',1,'Jordan Lee',6,'Inspection damage review','Medium'],
 ['RV-1037','RMA-803362','HPE MSA 2060','2S512003GH','Atlas Manufacturing',4,'Sam Patel',8,'','']
 ].map(([id,rma,product,serial,customer,stage,owner,days,issue,severity])=>{let created=new Date(NOW-days*86400000).toISOString();return {id,rma,product,serial,customer,stage,owner,created,shipment:'BOL-'+rma.slice(4),doc:'Sample delivery record.pdf',inspected:stage>=2,disposition:stage>=3?'Resale':'',approved:stage>=3,ack:stage===4,exceptions:issue?[{id:'EX-'+id.slice(3),title:issue,severity,owner,resolved:false,created,note:''}]:[],events:[{at:created,text:'Return received and digital traveler created',actor:'Maya Chen'},...(stage>0?[{at:new Date(new Date(created).getTime()+3600000).toISOString(),text:'Sample workflow history loaded · current stage: '+STAGES[stage],actor:owner}]:[])]}})}
let records;try{const saved=JSON.parse(localStorage.getItem(KEY));records=Array.isArray(saved)&&saved.every(r=>r.id&&Array.isArray(r.events)&&Array.isArray(r.exceptions))?saved:seed()}catch{records=seed()}
let page='overview',selected=null,tab='details',file=null,returnFocus=null;
const $=s=>document.querySelector(s);
const openIssues=r=>r.exceptions.filter(e=>!e.resolved);
const allIssues=()=>records.flatMap(r=>openIssues(r).map(e=>({...e,record:r})));
function save(){try{localStorage.setItem(KEY,JSON.stringify(records))}catch{toast('Browser storage unavailable. Keep this tab open; changes may not persist.')}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
function event(r,text){r.events.push({at:new Date().toISOString(),text,actor:'Alex Rivera · demo supervisor'});save()}
function stageTag(r){return `<span class="tag ${r.stage===4?'green':r.stage===2?'blue':''}">${STAGES[r.stage]}</span>`}
function statusTag(r){return openIssues(r).length?'<span class="tag amber">Blocked</span>':r.stage===4?'<span class="tag green">Completed</span>':'<span class="tag green">On track</span>'}
function title(eyebrow,name,desc,action=''){return `<div class="title-row"><div><div class="eyebrow">${eyebrow}</div><h1>${name}</h1><p>${desc}</p></div>${action}</div>`}
function table(rows){return `<div class="table-wrap"><table><thead><tr><th>Return / RMA</th><th>Product</th><th>Stage</th><th>Status</th><th>Age</th><th>Owner</th><th></th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td><button class="record" data-open="${esc(r.id)}">${esc(r.id)}</button><small>${esc(r.rma)}</small></td><td>${esc(r.product)}<small>${esc(r.serial)}</small></td><td>${stageTag(r)}</td><td>${statusTag(r)}</td><td>${elapsed(r)}d</td><td>${esc(r.owner)}</td><td><button class="link" data-open="${esc(r.id)}" aria-label="Open ${esc(r.id)}">↗</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty">No returns match these filters.</td></tr>'}</tbody></table></div>`}
function metrics(){const active=records.filter(r=>r.stage<4),blocked=active.filter(r=>openIssues(r).length),ready=active.filter(r=>r.stage===3&&!openIssues(r).length);return `<div class="cards">${[['Active returns',active.length,'Across four operational stages','▤'],['Blocked returns',blocked.length,'Require an owner action','⚑'],['Ready for handoff',ready.length,'Approved for resale inventory','↗'],['Completed returns',records.filter(r=>r.stage===4).length,'Sample dataset · all time','✓']].map(([t,v,n,i])=>`<div class="card"><div class="metric-top">${t}<span class="metric-icon">${metricIcon(i)}</span></div><div class="metric-value">${v}</div><div class="metric-note">${n}</div></div>`).join('')}</div>`}
function overview(){return title('OPERATIONS CONTROL TOWER','Every return. A clearer path.','A shared view of material flow, exceptions, and the next action.','<a class="primary" href="#receiving">＋ Receive a return</a>')+metrics()+`<div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Return flow</h2><p>Current work in progress · click a stage to explore</p></div><span class="tag green">Sample operations</span></div><div class="panel-body"><div class="flow">${STAGES.slice(0,4).map((s,i)=>{const n=records.filter(r=>r.stage===i).length;return `<a href="#returns" class="flow-stage" data-stage-link="${i}"><div class="stage-label">0${i+1} / ${s}</div><strong>${n}</strong><small>${records.filter(r=>r.stage===i&&openIssues(r).length).length} blocked · ${n} total items</small><div class="progress"><i style="width:${Math.min(n*25,100)}%"></i></div></a>`}).join('')}</div><div class="callout"><strong>Focus on the next action.</strong> ${allIssues().length} open exceptions need review. Clear missing information and approvals to keep returns moving.</div></div></section><section class="panel"><div class="panel-head"><h2>Needs attention</h2><a class="link" href="#exceptions">View all →</a></div><div class="panel-body">${allIssues().slice(0,3).map(e=>`<div class="attention"><span class="dot ${e.severity==='High'?'red':''}"></span><div><strong>${esc(e.title)}</strong><p>${esc(e.record.id)} · ${esc(e.owner)}</p></div><button class="link" data-open="${esc(e.record.id)}">↗</button></div>`).join('')||'<p>No open exceptions. Work is moving.</p>'}</div></section></div><section class="panel"><div class="panel-head"><div><h2>Active return workspace</h2><p>Trace each item from receipt to its next destination</p></div><a href="#returns" class="link">View all returns →</a></div>${table(records.filter(r=>r.stage<4).slice(0,6))}</section>`}
function returns(){return title('DIGITAL TRAVELERS','Return workspace','One record for every item. Ownership and history at every stage.','<button class="secondary" id="export">↓ Export CSV</button>')+`<div class="toolbar"><input id="search" aria-label="Search returns" placeholder="Search return, RMA, product, or serial…"><select id="stage-filter" aria-label="Filter stage"><option value="">All stages</option>${STAGES.map((s,i)=>`<option value="${i}">${s}</option>`).join('')}</select><select id="status-filter" aria-label="Filter status"><option value="">All statuses</option><option value="blocked">Blocked</option><option value="clear">No open exceptions</option></select><span id="result-count" class="tag"></span></div><section class="panel" id="return-table"></section>`}
function filterReturns(){const q=$('#search').value.toLowerCase(),s=$('#stage-filter').value,b=$('#status-filter').value;const rows=records.filter(r=>[r.id,r.rma,r.product,r.serial,r.customer].join(' ').toLowerCase().includes(q)&&(s===''||r.stage===+s)&&(!b||(b==='blocked'?openIssues(r).length:!openIssues(r).length)));$('#return-table').innerHTML=table(rows);$('#result-count').textContent=rows.length+' returns'}
function receiving(){return title('DOCUMENT TO DIGITAL TRAVELER','Receive a return','Capture once, validate the details, and start a traceable workflow.')+`<div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>New receipt</h2><p>Required fields are marked with an asterisk</p></div><span class="tag">01 / Receiving</span></div><div class="panel-body"><form id="receipt-form"><div class="upload"><div class="upload-icon">⇧</div><strong>Delivery documentation</strong><p>Choose a PDF, image, or text document. Demo files remain on this device.</p><input type="file" id="document" accept=".pdf,.png,.jpg,.jpeg,.txt" aria-label="Delivery document"><p id="file-status">No document selected</p><button type="button" class="secondary" id="sample">Use a sample document →</button></div><div class="notice">Sample extraction fills a known demonstration record. Arbitrary uploads require manual entry in this prototype; OCR is not connected. File contents are not retained after reload.</div><div class="form-grid"><div class="field"><label for="rma">RMA reference *</label><input id="rma" required maxlength="60" placeholder="RMA-803500"></div><div class="field"><label for="shipment">Delivery / BOL reference *</label><input id="shipment" required maxlength="60" placeholder="BOL-004812"></div><div class="field full"><label for="product">Product *</label><input id="product" required maxlength="150" placeholder="Product name or part number"></div><div class="field"><label for="serial">Serial number *</label><input id="serial" required maxlength="80" placeholder="Item serial number"></div><div class="field"><label for="customer">Customer / source *</label><input id="customer" required maxlength="120" placeholder="Organization name"></div><div class="field"><label for="owner">Assign to</label><select id="owner"><option>Maya Chen</option><option>Jordan Lee</option><option>Alex Rivera</option><option>Sam Patel</option></select></div><div class="field"><label for="initial-issue">Initial exception</label><select id="initial-issue"><option value="">No exception</option><option>Missing RMA authorization</option><option>Quantity discrepancy</option><option>Document requires clarification</option><option>Visible shipment damage</option></select></div><div class="full"><label><input type="checkbox" id="reviewed" required> I reviewed the item identifiers and delivery information *</label></div></div><div class="actions"><button class="primary" type="submit">Create digital traveler →</button></div></form></div></section><div><section class="panel"><div class="panel-head"><h2>A better first handoff</h2></div><div class="panel-body"><div class="section-label">01 / CAPTURE</div><p>Attach the delivery reference and identify the returned item.</p><div class="section-label">02 / VALIDATE</div><p>Review the source information and flag discrepancies early.</p><div class="section-label">03 / ASSIGN</div><p>Create an accountable next step with a full event history.</p><div class="callout">This demo creates one item per receipt. Multi-item shipments are included in the production proposal.</div></div></section><div class="assistant" style="margin-top:20px"><h3>✧ Receiving guidance</h3><p>Check the RMA, product, and serial together. A duplicate serial in an active return should be investigated before creating another traveler.</p><span class="tag">Rule-based guidance</span></div></div></div>`}
function exceptions(){return title('RESOLVE THE HOLD','Exception queue','Bring blocked returns back into flow with clear ownership and resolution.')+`<section class="panel"><div class="panel-head"><h2>${allIssues().length} open exceptions</h2><span class="tag amber">Review required</span></div><div class="table-wrap"><table><thead><tr><th>Exception</th><th>Return</th><th>Priority</th><th>Stage</th><th>Owner</th><th>Action</th></tr></thead><tbody>${allIssues().map(e=>`<tr><td><strong>${esc(e.title)}</strong><small>${esc(e.id)}</small></td><td><button class="record" data-open="${esc(e.record.id)}">${esc(e.record.id)}</button></td><td><span class="tag ${e.severity==='High'?'red':'amber'}">${esc(e.severity)}</span></td><td>${stageTag(e.record)}</td><td>${esc(e.owner)}</td><td><button class="link" data-open="${esc(e.record.id)}" data-tab="exceptions">Review →</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No open exceptions. All holds have been resolved.</td></tr>'}</tbody></table></div></section><div class="notice">Resolving an exception requires a resolution note. History is preserved on the digital traveler.</div>`}
function insights(){const active=records.filter(r=>r.stage<4);return title('UNDERSTAND THE FLOW','Process insights','Operational signals from recorded sample events. No savings claims or predictive models.')+metrics()+`<div class="grid-2"><section class="panel"><div class="panel-head"><h2>Work in progress by stage</h2><span class="tag">Live demo records</span></div><div class="panel-body">${STAGES.slice(0,4).map((s,i)=>{let n=active.filter(r=>r.stage===i).length;return `<div class="bar-row"><span>${s}</span><div class="bar"><i style="width:${n/Math.max(1,...STAGES.slice(0,4).map((_,j)=>active.filter(r=>r.stage===j).length))*100}%"></i></div><strong>${n}</strong></div>`}).join('')}<div class="callout">Counts reflect current traveler stages. A high queue count alone does not establish a bottleneck; compare arrival rates, staffing, and waiting time.</div></div></section><section class="panel"><div class="panel-head"><h2>Data and measurement</h2></div><div class="panel-body"><div class="stat-line"><span>Active returns older than 3 days</span><strong>${active.filter(r=>elapsed(r)>3).length}</strong></div><div class="stat-line"><span>Open exceptions</span><strong>${allIssues().length}</strong></div><div class="stat-line"><span>Unassigned active returns</span><strong>${active.filter(r=>!r.owner).length}</strong></div><div class="stat-line"><span>Inventory interface</span><span class="tag amber">Simulated</span></div><p style="font-size:11px;margin-top:17px">Age uses elapsed calendar days since receipt. Sample records do not support a validated cycle-time baseline or an ROI estimate.</p></div></section></div><section class="assistant"><h2>✧ Operations briefing</h2><p>${active.length} returns are active across the sample workflow. ${allIssues().length} exceptions require review. ${active.filter(r=>r.stage===3&&!openIssues(r).length).length} items are ready for a simulated inventory handoff.</p><p>Recommended next step: review high-priority exceptions, confirm the evidence with the assigned owner, and document the resolution before advancing the item.</p><span class="tag">Deterministic summary of current records · No external AI service</span></section>`}
function render(){page=location.hash.slice(1)||'overview';if(!['overview','returns','receiving','exceptions','insights'].includes(page))page='overview';$('#main').innerHTML=({overview,returns,receiving,exceptions,insights}[page])();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#page-label').textContent={overview:'Overview',returns:'Return workspace',receiving:'Receiving',exceptions:'Exceptions',insights:'Process insights'}[page];$('#exception-count').textContent=allIssues().length;if(page==='returns'){if(window.pendingStage!==undefined){$('#stage-filter').value=window.pendingStage;delete window.pendingStage}filterReturns();['search','stage-filter','status-filter'].forEach(id=>$('#'+id).addEventListener('input',filterReturns));$('#export').onclick=exportCSV}if(page==='receiving')bindReceipt()}
function bindReceipt(){$('#document').onchange=e=>{const f=e.target.files[0];if(f&&f.size>15*1024*1024){e.target.value='';file=null;toast('Choose a file smaller than 15 MB.');return}file=f?f.name:null;$('#file-status').textContent=f?f.name+' · manual entry required':'No document selected'};$('#sample').onclick=()=>{file='Sample delivery record · BOL-004812.pdf';$('#file-status').textContent=file+' · known sample fields populated';for(const [id,v] of Object.entries({rma:'RMA-803500',shipment:'BOL-004812',product:'HPE ProLiant DL380 Gen11',serial:'CZJ42982NEW',customer:'Northstar Financial'}))$('#'+id).value=v;$('#reviewed').checked=false;toast('Sample fields populated. Review the details before creating a traveler.')};$('#receipt-form').onsubmit=e=>{e.preventDefault();let data={};for(const id of ['rma','shipment','product','serial','customer','owner'])data[id]=$('#'+id).value.trim();if(Object.values(data).some(v=>!v)){toast('Complete all required fields.');return}if(records.some(r=>r.stage<4&&r.serial.toLowerCase()===data.serial.toLowerCase())){toast('This serial already has an active return. Review the existing traveler.');return}const id='RV-'+(Math.max(...records.map(r=>Number(r.id.slice(3))))+1),created=new Date().toISOString(),issue=$('#initial-issue').value;const r={...data,id,created,stage:0,doc:file||'No document attached',inspected:false,disposition:'',approved:false,ack:false,exceptions:issue?[{id:'EX-'+id.slice(3),title:issue,severity:'Medium',owner:data.owner,resolved:false,created,note:''}]:[],events:[{at:created,text:'Traveler created after manual review · '+(file||'manual receipt'),actor:'Alex Rivera · demo supervisor'}]};records.unshift(r);save();file=null;history.replaceState(null,'','#returns');render();openRecord(id);toast('Digital traveler created: '+id)}}
function openRecord(id,newTab='details'){selected=id;tab=newTab;returnFocus=document.activeElement;$('#drawer').hidden=false;$('#drawer-backdrop').hidden=false;document.body.style.overflow='hidden';drawRecord();$('#close-drawer').focus()}
function closeRecord(){$('#drawer').hidden=true;$('#drawer-backdrop').hidden=true;document.body.style.overflow='';selected=null;if(returnFocus?.isConnected)returnFocus.focus()}
function drawRecord(){const r=records.find(x=>x.id===selected);if(!r)return;const blocked=!!openIssues(r).length;$('#drawer').innerHTML=`<div class="drawer-top"><div><div class="eyebrow">DIGITAL TRAVELER</div><h1>${esc(r.id)}</h1><p>${esc(r.product)}</p></div><button class="close" id="close-drawer" aria-label="Close traveler">×</button></div><div class="detail-stages">${STAGES.map((s,i)=>`<span class="${i<r.stage?'done':i===r.stage?'current':''}">${i<r.stage?'✓ ':''}${s}</span>`).join('')}</div><div class="detail-info">${[['RMA reference',r.rma],['Serial number',r.serial],['Customer / source',r.customer],['Delivery reference',r.shipment],['Owner',r.owner],['Received',date(r.created)]].map(([k,v])=>`<div><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="tabs">${[['details','Work & decisions'],['exceptions','Exceptions ('+openIssues(r).length+')'],['history','Event history']].map(([k,t])=>`<button data-detail-tab="${k}" class="${tab===k?'active':''}">${t}</button>`).join('')}</div><div id="detail-content">${tab==='history'?`<div class="timeline">${[...r.events].reverse().map(e=>`<div class="event"><strong>${esc(e.text)}</strong><small>${esc(e.actor)} · ${date(e.at)}</small></div>`).join('')}</div>`:tab==='exceptions'?exceptionDetail(r):workDetail(r)}</div><div class="section-label">RECORD ASSISTANT</div><div class="assistant"><h3>✧ Suggested next action</h3><p>${blocked?'Resolve '+esc(openIssues(r).map(e=>e.title).join('; '))+' with the assigned owners before advancing.':r.stage===0?'Validate the receipt and send this item to inspection.':r.stage===1?'Complete the inspection checklist and record the observed condition.':r.stage===2?'Select a disposition and record a supervisor approval.':r.stage===3?'Review the approved record, then simulate the inventory handoff.':'This traveler is closed. Its history remains available for review.'}</p><span class="tag">Rule-based · based on this traveler</span></div>`;$('#close-drawer').onclick=closeRecord;document.querySelectorAll('[data-detail-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.detailTab;drawRecord()});bindDetail(r)}
function workDetail(r){return `<div class="stat-line"><span>Current status</span>${statusTag(r)}</div><div class="stat-line"><span>Source document reference</span><strong>${esc(r.doc)}</strong></div><div class="stat-line"><span>Inspection recorded</span><strong>${r.inspected?'Yes':'Not yet'}</strong></div><div class="stat-line"><span>Approved disposition</span><strong>${r.approved?esc(r.disposition):'Pending'}</strong></div>${r.stage===1?`<form class="detail-form" id="inspection-form"><h3>Record inspection</h3><label for="condition">Observed condition *</label><select id="condition"><option>Passed visual and functional checks</option><option>Repair required</option><option>Damage found — requires review</option></select><label for="inspection-note">Inspection notes *</label><textarea id="inspection-note" required placeholder="Record checks performed and findings"></textarea><button class="primary" style="margin-top:12px">Save inspection</button></form>`:''}${r.stage===2?`<form class="detail-form" id="approval-form"><h3>Disposition review</h3><label for="disposition">Disposition *</label><select id="disposition"><option>Resale</option><option>Repair</option><option>Parts recovery</option><option>Recycling</option></select><label for="approval-note">Decision rationale *</label><textarea id="approval-note" required placeholder="Explain the disposition and supporting evidence"></textarea><label><input type="checkbox" required style="width:auto"> Approve as demo supervisor</label><button class="primary">Record approval</button><p style="font-size:10px">Only approved resale items use the demo inventory handoff. Other outcomes close with a recorded disposition.</p></form>`:''}<div class="actions">${r.stage<4?`<button class="primary" id="advance" ${openIssues(r).length||r.stage===1&&!r.inspected||r.stage===2&&!r.approved?'disabled':''}>${r.stage===3?'Simulate inventory handoff & close':r.stage===2&&r.approved&&r.disposition!=='Resale'?'Close with approved disposition':'Move to '+STAGES[r.stage+1]} →</button>`:`<span class="tag green">${r.ack?'Simulated inventory acknowledgment received':'Closed with approved disposition'}</span>`}</div>${openIssues(r).length?'<div class="notice">This item is on hold. Resolve its open exceptions before moving forward.</div>':''}<div class="section-label">OWNERSHIP</div><form id="owner-form" class="toolbar"><select id="record-owner" aria-label="Assign traveler owner">${['Maya Chen','Jordan Lee','Alex Rivera','Sam Patel'].map(n=>`<option ${n===r.owner?'selected':''}>${n}</option>`).join('')}</select><button class="secondary">Reassign</button></form>`}
function exceptionDetail(r){return `${r.exceptions.map(e=>`<div class="detail-form"><div style="display:flex;justify-content:space-between;gap:10px"><h3>${esc(e.title)}</h3><span class="tag ${e.resolved?'green':'amber'}">${e.resolved?'Resolved':esc(e.severity)}</span></div><p style="font-size:11px">${esc(e.id)} · ${esc(e.owner)}</p>${e.resolved?`<p>${esc(e.note)}</p><button class="link" data-reopen="${esc(e.id)}">Reopen exception</button>`:`<form data-resolve="${esc(e.id)}"><label>Owner<select name="owner">${['Maya Chen','Jordan Lee','Alex Rivera','Sam Patel'].map(n=>`<option ${n===e.owner?'selected':''}>${n}</option>`).join('')}</select></label><label>Resolution note *<textarea name="note" required placeholder="Document the evidence and action taken"></textarea></label><button class="primary">Resolve exception</button></form>`}</div>`).join('')||'<p>No exceptions recorded for this traveler.</p>'}${r.stage<4?`<form class="detail-form" id="add-exception"><h3>Flag a new issue</h3><label for="issue-title">Issue *</label><input id="issue-title" required maxlength="180" placeholder="Describe the discrepancy"><label for="severity">Priority</label><select id="severity"><option>Medium</option><option>High</option><option>Low</option></select><button class="secondary" style="margin-top:13px">Add exception</button></form>`:''}`}
function bindDetail(r){const advance=$('#advance');if(advance)advance.onclick=()=>{if(openIssues(r).length||r.stage===1&&!r.inspected||r.stage===2&&!r.approved)return;if(r.stage===3){r.ack=true;r.stage=4;event(r,'Simulated inventory handoff acknowledged · traveler closed')}else if(r.stage===2&&r.disposition!=='Resale'){r.stage=4;event(r,'Closed with approved disposition: '+r.disposition+' · no inventory transaction')}else{r.stage++;event(r,'Moved to '+STAGES[r.stage])}render();drawRecord();toast('Traveler updated')};const inspection=$('#inspection-form');if(inspection)inspection.onsubmit=e=>{e.preventDefault();const note=$('#inspection-note').value.trim();if(!note)return;const condition=$('#condition').value;r.inspected=true;event(r,'Inspection recorded: '+condition+' · '+note);if(condition.startsWith('Damage')){r.exceptions.push({id:'EX-'+Date.now(),title:'Inspection damage review',severity:'High',owner:r.owner,resolved:false,created:new Date().toISOString(),note:''});event(r,'Damage exception created; supervisor review required')}render();drawRecord();toast('Inspection recorded')};const approval=$('#approval-form');if(approval)approval.onsubmit=e=>{e.preventDefault();const note=$('#approval-note').value.trim();if(!note)return;r.disposition=$('#disposition').value;r.approved=true;event(r,'Disposition approved: '+r.disposition+' · '+note);drawRecord();toast('Supervisor approval recorded')};const owner=$('#owner-form');if(owner)owner.onsubmit=e=>{e.preventDefault();const n=$('#record-owner').value;r.owner=n;event(r,'Traveler reassigned to '+n);render();drawRecord();toast('Owner updated')};document.querySelectorAll('[data-resolve]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const ex=r.exceptions.find(x=>x.id===form.dataset.resolve),note=form.elements.note.value.trim();if(!note)return;ex.owner=form.elements.owner.value;ex.note=note;ex.resolved=true;event(r,'Exception resolved: '+ex.title+' · owner: '+ex.owner+' · '+note);render();drawRecord();toast('Exception resolved')});document.querySelectorAll('[data-reopen]').forEach(b=>b.onclick=()=>{const ex=r.exceptions.find(x=>x.id===b.dataset.reopen);ex.resolved=false;event(r,'Exception reopened: '+ex.title);render();drawRecord()});const add=$('#add-exception');if(add)add.onsubmit=e=>{e.preventDefault();const title=$('#issue-title').value.trim();if(!title)return;r.exceptions.push({id:'EX-'+Date.now(),title,severity:$('#severity').value,owner:r.owner,resolved:false,created:new Date().toISOString(),note:''});event(r,'Exception created: '+title);render();drawRecord();toast('Exception added; traveler is on hold')}}
function exportCSV(){const cell=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'").replace(/"/g,'""')+'"';const csv=[['Return','RMA','Product','Serial','Stage','Owner','Open exceptions','Received'],...records.map(r=>[r.id,r.rma,r.product,r.serial,STAGES[r.stage],r.owner,openIssues(r).length,r.created])].map(row=>row.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='hpe-revolve-returns.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Return register exported')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-open]');if(b)openRecord(b.dataset.open,b.dataset.tab||'details');const s=e.target.closest('[data-stage-link]');if(s){window.pendingStage=s.dataset.stageLink;if(page==='returns'){render()}}});$('#drawer-backdrop').onclick=closeRecord;document.addEventListener('keydown',e=>{if(!selected)return;if(e.key==='Escape')closeRecord();if(e.key==='Tab'){const nodes=[...$('#drawer').querySelectorAll('button,input,select,textarea,a[href]')].filter(n=>!n.disabled&&n.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});$('#reset').onclick=()=>{if(confirm('Reset all sample records and discard your demo changes?')){records=seed();save();closeRecord();render();toast('Sample data restored')}};window.addEventListener('hashchange',()=>{closeRecord();render()});render();
